def solve(observation):
    data = observation['data']
    N = len(data)
    half = N // 2

    # Initialize grid: 0 = unknown, 1 = B, 2 = W
    grid = [[0]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] == 'B':
                grid[r][c] = 1
            elif data[r][c] == 'W':
                grid[r][c] = 2

    def is_valid_partial(grid):
        for r in range(N):
            bc = sum(1 for c in range(N) if grid[r][c] == 1)
            wc = sum(1 for c in range(N) if grid[r][c] == 2)
            if bc > half or wc > half:
                return False
            for c in range(N-2):
                if grid[r][c] != 0 and grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                    return False
        for c in range(N):
            bc = sum(1 for r in range(N) if grid[r][c] == 1)
            wc = sum(1 for r in range(N) if grid[r][c] == 2)
            if bc > half or wc > half:
                return False
            for r in range(N-2):
                if grid[r][c] != 0 and grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                    return False
        return True

    def is_complete_valid(grid):
        for r in range(N):
            if sum(1 for c in range(N) if grid[r][c] == 1) != half:
                return False
            if sum(1 for c in range(N) if grid[r][c] == 2) != half:
                return False
        for c in range(N):
            if sum(1 for r in range(N) if grid[r][c] == 1) != half:
                return False
            if sum(1 for r in range(N) if grid[r][c] == 2) != half:
                return False
        rows = [tuple(grid[r]) for r in range(N)]
        if len(set(rows)) != N:
            return False
        cols = [tuple(grid[r][c] for r in range(N)) for c in range(N)]
        if len(set(cols)) != N:
            return False
        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] != 0:
                        continue
                    for val in [1, 2]:
                        opp = 3 - val
                        # Check triple in row
                        if c >= 2 and grid[r][c-1] == val and grid[r][c-2] == val:
                            grid[r][c] = opp; changed = True; break
                        if c >= 1 and c < N-1 and grid[r][c-1] == val and grid[r][c+1] == val:
                            grid[r][c] = opp; changed = True; break
                        if c < N-2 and grid[r][c+1] == val and grid[r][c+2] == val:
                            grid[r][c] = opp; changed = True; break
                        # Check triple in col
                        if r >= 2 and grid[r-1][c] == val and grid[r-2][c] == val:
                            grid[r][c] = opp; changed = True; break
                        if r >= 1 and r < N-1 and grid[r-1][c] == val and grid[r+1][c] == val:
                            grid[r][c] = opp; changed = True; break
                        if r < N-2 and grid[r+1][c] == val and grid[r+2][c] == val:
                            grid[r][c] = opp; changed = True; break
                    else:
                        # Count constraint
                        row_b = sum(1 for cc in range(N) if grid[r][cc] == 1)
                        row_w = sum(1 for cc in range(N) if grid[r][cc] == 2)
                        if row_b == half:
                            grid[r][c] = 2; changed = True; continue
                        if row_w == half:
                            grid[r][c] = 1; changed = True; continue
                        col_b = sum(1 for rr in range(N) if grid[rr][c] == 1)
                        col_w = sum(1 for rr in range(N) if grid[rr][c] == 2)
                        if col_b == half:
                            grid[r][c] = 2; changed = True; continue
                        if col_w == half:
                            grid[r][c] = 1; changed = True; continue
        return grid

    def solve_recursive(grid):
        grid = propagate(grid)
        if not is_valid_partial(grid):
            return None

        # Find first empty
        best = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    if best is None:
