            if col.count(0) != half_n or col.count(1) != half_n:
                return False
        # No three consecutive
        for r in range(N):
            for c in range(M - 2):
                if grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                    return False
        for c in range(M):
            for r in range(N - 2):
                if grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                    return False
        return True

    def propagate(domain):
