    def deep_copy_domain(domain):
        return [[s.copy() for s in row] for row in domain]

    def solve_recursive(domain):
        result = propagate(domain)
        if result is False:
            return None

        # Check if solved
        all_fixed = True
        best_cell = None
        for r in range(N):
            for c in range(M):
                if len(domain[r][c]) == 0:
                    return None
                if len(domain[r][c]) > 1:
                    all_fixed = False
                    if best_cell is None:
                        best_cell = (r, c)

        if all_fixed:
            # Verify solution
            grid = [[next(iter(domain[r][c])) for c in range(M)] for r in range(N)]
            # Check three consecutive
            for r in range(N):
                for c in range(M - 2):
                    if grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                        return None
            for c in range(M):
                for r in range(N - 2):
                    if grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                        return None
            # Check counts
            for r in range(N):
                if sum(1 for c in range(M) if grid[r][c] == 0) != half_m:
                    return None
            for c in range(M):
                if sum(1 for r in range(N) if grid[r][c] == 0) != half_n:
                    return None
            return grid

        r, c = best_cell
        for val in sorted(domain[r][c]):
            new_domain = deep_copy_domain(domain)
            new_domain[r][c] = {val}
            result = solve_recursive(new_domain)
            if result is not None:
                return result

        return None

    grid = solve_recursive(domain)

    if grid is None:
        return "No Solution"

    result = [['B' if grid[r][c] == 0 else 'W' for c in range(M)] for r in range(N)]
    return result


