def solve(observation):
    data = observation['data']
    N = len(data)
    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    # Parse constraints
    h_constraints = {}  # (row, col) -> '<' or '>' meaning grid[row][col] < or > grid[row][col+1]
    for key, val in horizontal.items():
        key = key.strip('()')
        parts = key.split(',')
        r = float(parts[0].strip())
        c = float(parts[1].strip())
        # Horizontal constraint at (row, col+0.5) means between (row, col) and (row, col+1)
        row = int(r)
        col = int(c - 0.5)
        h_constraints[(row, col)] = val

    v_constraints = {}  # (row, col) -> '^' or 'v' meaning grid[row][col] ^ or v grid[row+1][col]
    for key, val in vertical.items():
        key = key.strip('()')
        parts = key.split(',')
        r = float(parts[0].strip())
        c = float(parts[1].strip())
        # Vertical constraint at (row+0.5, col) means between (row, col) and (row+1, col)
        row = int(r - 0.5)
        col = int(c)
        v_constraints[(row, col)] = val

    # Initialize possible values for each cell
    possible = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Set givens
    grid = [[0]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]
                possible[r][c] = {data[r][c]}

    def is_valid_assignment(r, c, val):
        # Check row uniqueness
        for cc in range(N):
            if cc != c and grid[r][cc] == val:
                return False
        # Check col uniqueness
        for rr in range(N):
            if rr != r and grid[rr][c] == val:
                return False
        return True

    def check_inequality_possible(r, c, val):
        """Check if assigning val to (r,c) is consistent with inequality constraints."""
        # Horizontal: (r, c) with (r, c+1)
        if (r, c) in h_constraints:
            sym = h_constraints[(r, c)]
            other = possible[r][c+1]
            if grid[r][c+1] != 0:
                other_vals = {grid[r][c+1]}
            else:
                other_vals = other
            if sym == '<':
                if not any(val < ov for ov in other_vals):
                    return False
            else:  # '>'
                if not any(val > ov for ov in other_vals):
                    return False

        # Horizontal: (r, c-1) with (r, c)
        if (r, c-1) in h_constraints:
            sym = h_constraints[(r, c-1)]
            if grid[r][c-1] != 0:
                other_vals = {grid[r][c-1]}
            else:
                other_vals = possible[r][c-1]
            if sym == '<':
                if not any(ov < val for ov in other_vals):
                    return False
            else:  # '>'
                if not any(ov > val for ov in other_vals):
                    return False

        # Vertical: (r, c) with (r+1, c)
        if (r, c) in v_constraints:
            sym = v_constraints[(r, c)]
            if grid[r+1][c] != 0:
                other_vals = {grid[r+1][c]}
            else:
                other_vals = possible[r+1][c]
            if sym == '^':
                # grid[r][c] > grid[r+1][c]
                if not any(val > ov for ov in other_vals):
                    return False
            else:  # 'v'
                # grid[r][c] < grid[r+1][c]
                if not any(val < ov for ov in other_vals):
                    return False

        # Vertical: (r-1, c) with (r, c)
        if (r-1, c) in v_constraints:
            sym = v_constraints[(r-1, c)]
            if grid[r-1][c] != 0:
                other_vals = {grid[r-1][c]}
            else:
                other_vals = possible[r-1][c]
            if sym == '^':
                # grid[r-1][c] > grid[r][c]
                if not any(ov > val for ov in other_vals):
                    return False
            else:  # 'v'
                # grid[r-1][c] < grid[r][c]
                if not any(ov < val for ov in other_vals):
                    return False

        return True

    def propagate():
        """Constraint propagation. Returns False if contradiction found."""
        changed = True
        while changed:
            changed = False

            # Apply givens / naked singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] != 0:
                        val = grid[r][c]
                        # Remove from row
                        for cc in range(N):
                            if cc != c and val in possible[r][cc]:
                                possible[r][cc].discard(val)
                                changed = True
                                if len(possible[r][cc]) == 0:
                                    return False
                        # Remove from col
                        for rr in range(N):
                            if rr != r and val in possible[rr][c]:
                                possible[rr][c].discard(val)
                                changed = True
                                if len(possible[rr][c]) == 0:
                                    return False
