                        used_row = set()
                        used_col = set()
                        for cc in range(N):
                            if grid[r][cc] != 0:
                                used_row.add(grid[r][cc])
                        for rr in range(N):
                            if grid[rr][c] != 0:
                                used_col.add(grid[rr][c])
                        before = len(possible[r][c])
                        possible[r][c] -= (used_row | used_col)
                        if len(possible[r][c]) < before:
                            changed = True
                        if len(possible[r][c]) == 0:
                            return False

            # Apply inequality constraints to prune
            for (r, c), sym in h_constraints.items():
                # grid[r][c] sym grid[r][c+1]
                if sym == '<':
