def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # Extract islands
    islands = {}
    island_list = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                islands[(r, c)] = data[r][c]
                island_list.append((r, c))

    # Find potential neighbors in 4 directions for each island
    # For each island, find the nearest island in each direction (up, down, left, right)
    def find_neighbors():
        neighbors = {isl: [] for isl in island_list}
        for isl in island_list:
            r, c = isl
            # Right
            for c2 in range(c + 1, cols):
                if (r, c2) in islands:
                    neighbors[isl].append((r, c2))
                    break
            # Down
            for r2 in range(r + 1, rows):
                if (r2, c) in islands:
                    neighbors[isl].append((r2, c))
                    break
        # Make bidirectional pairs
        edges = []
        edge_set = set()
        for isl in island_list:
            for nb in neighbors[isl]:
                pair = (min(isl, nb), max(isl, nb))
                if pair not in edge_set:
                    edge_set.add(pair)
                    edges.append(pair)
        return edges

    edges = find_neighbors()

    # For each island, track which edges are incident
    island_edges = {isl: [] for isl in island_list}
    for i, (a, b) in enumerate(edges):
        island_edges[a].append(i)
        island_edges[b].append(i)

    # Bridge counts: 0, 1, or 2 for each edge
    # We'll use constraint propagation + backtracking

    # For each edge, possible values: 0, 1, 2
    # But constrained by island capacities and crossing

    # Check if two edges cross
    def edges_cross(e1, e2):
        (r1a, c1a), (r1b, c1b) = e1
        (r2a, c2a), (r2b, c2b) = e2
        # e1 horizontal, e2 vertical or vice versa
        if r1a == r1b and c2a == c2b:
            # e1 is horizontal, e2 is vertical
            h_row = r1a
            h_c_min, h_c_max = min(c1a, c1b), max(c1a, c1b)
            v_col = c2a
            v_r_min, v_r_max = min(r2a, r2b), max(r2a, r2b)
            if v_r_min < h_row < v_r_max and h_c_min < v_col < h_c_max:
                return True
        elif c1a == c1b and r2a == r2b:
            # e1 is vertical, e2 is horizontal
            v_col = c1a
            v_r_min, v_r_max = min(r1a, r1b), max(r1a, r1b)
            h_row = r2a
            h_c_min, h_c_max = min(c2a, c2b), max(c2a, c2b)
            if v_r_min < h_row < v_r_max and h_c_min < v_col < h_c_max:
                return True
        return False

    # Precompute crossing pairs
    num_edges = len(edges)
    crossing = [[] for _ in range(num_edges)]
    for i in range(num_edges):
        for j in range(i + 1, num_edges):
            if edges_cross(edges[i], edges[j]):
                crossing[i].append(j)
                crossing[j].append(i)

