    # This is already handled by finding nearest neighbor only

    # State: bridge_count[i] for each edge i, values 0..2
    # Constraints:
    # 1. For each island, sum of bridges on incident edges == island number
    # 2. If two edges cross and both > 0, invalid
    # 3. All islands connected

    # Use constraint propagation with min/max possible for each edge
    # lo[i], hi[i] = min and max bridges for edge i

    lo = [0] * num_edges
    hi = [2] * num_edges

    def propagate(lo, hi):
        changed = True
        while changed:
            changed = False
            for isl in island_list:
                target = islands[isl]
                eidxs = island_edges[isl]
                current_min = sum(lo[e] for e in eidxs)
                current_max = sum(hi[e] for e in eidxs)

                if current_min > target or current_max < target:
                    return False

                # If current_min == target, all unfixed edges must be at lo
                if current_min == target:
                    for e in eidxs:
                        if hi[e] > lo[e]:
                            hi[e] = lo[e]
                            changed = True

                # If current_max == target, all unfixed edges must be at hi
                if current_max == target:
                    for e in eidxs:
                        if lo[e] < hi[e]:
                            lo[e] = hi[e]
                            changed = True

                # More advanced: if removing one edge's contribution...
                for e in eidxs:
                    others_min = current_min - lo[e]
                    others_max = current_max - hi[e]
                    # This edge needs at least target - others_max
                    need_min = target - (current_max - hi[e])
                    # wait, let me recalculate
                    # sum of others max = current_max - hi[e] ... no
                    # others_max = sum of hi for other edges
                    om = current_max - hi[e]
                    # this edge needs at least target - om
                    need_lo = target - om
                    if need_lo < 0:
                        need_lo = 0
                    # others_min = current_min - lo[e]
                    omn = current_min - lo[e]
                    need_hi = target - omn
                    if need_hi > 2:
                        need_hi = 2

                    if need_lo > lo[e]:
                        lo[e] = need_lo
                        changed = True
                    if need_hi < hi[e]:
                        hi[e] = need_hi
                        changed = True

                    if lo[e] > hi[e]:
                        return False

            # Crossing constraints
            for i in range(num_edges):
                if lo[i] > 0:
                    for j in crossing[i]:
                        if lo[j] > 0:
                            return False
                        if hi[j] > 0:
                            hi[j] = 0
                            changed = True

            # If an edge has hi > 0 but all crossing edges also have hi > 0,
            # we can't deduce much yet. But if lo[i] > 0, crossing must be 0.

        return True

    def is_connected(assignment):
        # Check if all islands with at least one bridge are connected
        # Actually all islands must be connected
        if len(island_list) <= 1:
            return True

        adj = {isl: [] for isl in island_list}
        for i, (a, b) in enumerate(edges):
            if assignment[i] > 0:
                adj[a].append(b)
