    data = observation['data']
    N = len(data)

    # state: 0 = unknown, 1 = white, 2 = black
    state = [[0]*N for _ in range(N)]

    # For constraint propagation, track possible states
    # We'll use sets for row/col uniqueness tracking

    from collections import deque

    def is_valid_partial():
        # Check no two adjacent black cells
        for r in range(N):
            for c in range(N):
                if state[r][c] == 2:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 2:
                            return False
        return True

    def check_no_adjacent_black(r, c):
        if state[r][c] == 2:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 2:
                    return False
        return True

    def check_uniqueness():
        # For each row, check no duplicate white values
        for r in range(N):
            seen = {}
            for c in range(N):
                if state[r][c] == 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen[v] = True
        for c in range(N):
            seen = {}
            for r in range(N):
                if state[r][c] == 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen[v] = True
        return True

    def check_row_col_possible():
        # Check that for each row, remaining unknowns can resolve duplicates
        for r in range(N):
            white_vals = {}
            unknown_vals = {}
            for c in range(N):
                v = data[r][c]
                if state[r][c] == 1:
                    if v in white_vals:
                        return False
                    white_vals[v] = c
                elif state[r][c] == 0:
                    if v not in unknown_vals:
                        unknown_vals[v] = []
                    unknown_vals[v].append(c)
            # For values that are already white, any unknown with same value must be blackable
            # (no forced conflict)
        for c in range(N):
            white_vals = {}
            for r in range(N):
                v = data[r][c]
                if state[r][c] == 1:
                    if v in white_vals:
                        return False
                    white_vals[v] = r
        return True

    def connectivity_check():
        # Check all white cells (state==1) and unknown cells (state==0) can potentially connect
        # More importantly, check that current white cells are connected through white+unknown
        white_cells = []
        for r in range(N):
            for c in range(N):
                if state[r][c] != 2:
                    white_cells.append((r, c))
        if not white_cells:
            return True
        visited = set()
        q = deque([white_cells[0]])
        visited.add(white_cells[0])
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in visited and state[nr][nc] != 2:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(white_cells)

    def strict_connectivity_check():
        # Only check confirmed white cells are connected through non-black
        white_cells = [(r,c) for r in range(N) for c in range(N) if state[r][c] == 1]
        if len(white_cells) <= 1:
            return True
        visited = set()
        q = deque([white_cells[0]])
        visited.add(white_cells[0])
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
