        changed = True
        while changed:
            changed = False

            # Rule 1: If a cell is black, all neighbors must be white
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2:
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 0:
