            if not strict_connectivity_check():
                return False

        return True

    def is_complete():
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    return False
        return True

    def find_best_cell():
        # Find unknown cell with most constraints
        best = None
        best_score = -1
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    score = 0
                    v = data[r][c]
                    # Count how many same-value cells in row/col are unknown
                    for c2 in range(N):
                        if c2 != c and data[r][c2] == v and state[r][c2] != 2:
                            score += 1
                    for r2 in range(N):
                        if r2 != r and data[r2][c] == v and state[r2][c] != 2:
                            score += 1
                    # Count black neighbors
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
