        return [row[:] for row in state]

    def restore_state(saved):
        for r in range(N):
            for c in range(N):
                state[r][c] = saved[r][c]

    def dfs():
        result = propagate()
        if not result:
            return False

        if not connectivity_check():
            return False

        if is_complete():
