        for r in range(N):
            if cnt[data[r][c]] == 1 and state[r][c] == 0:
                state[r][c] = 1

    if dfs():
        result = [[None]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if state[r][c] == 2:
                    result[r][c] = 'B'
        return result

    return "No Solution"

