def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(region)

    # Build region membership
    region_cells = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    # Cell to region mapping
    cell_region = {}
    for r in range(N):
        for c in range(N):
            cell_region[(r, c)] = region[r][c]

    # Initialize possible values
    possible = [[set() for _ in range(N)] for _ in range(N)]
    grid = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]
                possible[r][c] = set()
            else:
                possible[r][c] = set(range(1, N + 1))

    # Remove initial constraints
    for r in range(N):
        for c in range(N):
            if grid[r][c] != 0:
                val = grid[r][c]
                # Remove from row
                for cc in range(N):
                    possible[r][cc].discard(val)
                # Remove from col
                for rr in range(N):
                    possible[rr][c].discard(val)
                # Remove from region
                rid = cell_region[(r, c)]
                for (rr, cc) in region_cells[rid]:
                    possible[rr][cc].discard(val)

    def propagate():
        changed = True
        while changed:
            changed = False
            # Naked singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0 and len(possible[r][c]) == 1:
                        val = next(iter(possible[r][c]))
                        grid[r][c] = val
