OBSERVATION = {'row_sum': [6, 4, 9, 7, 11], 'col_sum': [4, 9, 3, 7, 13]}

def solve(observation):
    row_sums = observation['row_sum']
    col_sums = observation['col_sum']
    nrows = len(row_sums)
    ncols = len(col_sums)

    # Column weights (1-indexed): 1, 2, 3, 4, 5
    col_weights = list(range(1, ncols + 1))
    # Row weights (1-indexed): 1, 2, 3, 4, 5
    row_weights = list(range(1, nrows + 1))

    # For each row, the sum of col_weights of black cells must equal row_sums[r]
    # For each col, the sum of row_weights of black cells must equal col_sums[c]

    # grid[r][c] = 1 if black, 0 otherwise
    # Row constraint: sum over c of (grid[r][c] * col_weights[c]) == row_sums[r]
    # Col constraint: sum over r of (grid[r][c] * row_weights[r]) == col_sums[c]

    # Strategy: enumerate valid subsets for each row, then use backtracking with column constraint propagation

    from itertools import combinations

    # Precompute valid column subsets for each row
    row_valid = []
    for r in range(nrows):
        target = row_sums[r]
        valid = []
        # Try all subsets of columns
        for mask in range(1 << ncols):
            s = 0
            for c in range(ncols):
                if mask & (1 << c):
                    s += col_weights[c]
            if s == target:
                valid.append(mask)
        row_valid.append(valid)

    # Backtracking: assign row by row, track remaining column sums
    col_remaining = list(col_sums)

    solution = [None] * nrows

    def backtrack(r):
        if r == nrows:
            # Check all column remainders are 0
            return all(cr == 0 for cr in col_remaining)

        rw = row_weights[r]
        remaining_row_weight_sum = sum(row_weights[r+1:nrows])

        for mask in row_valid[r]:
            # Check feasibility: for each column, subtracting rw if black shouldn't go negative
            # and remaining rows should be able to fill the rest
            feasible = True
            for c in range(ncols):
                if mask & (1 << c):
                    new_rem = col_remaining[c] - rw
                else:
                    new_rem = col_remaining[c]

                if new_rem < 0:
                    feasible = False
                    break
                # Check if remaining rows can still achieve the target
                # Max contribution from remaining rows = remaining_row_weight_sum
                if new_rem > remaining_row_weight_sum:
                    feasible = False
                    break

            if not feasible:
                continue

            # Apply
            for c in range(ncols):
                if mask & (1 << c):
                    col_remaining[c] -= rw
            solution[r] = mask

            if backtrack(r + 1):
                return True

            # Undo
            for c in range(ncols):
                if mask & (1 << c):
                    col_remaining[c] += rw

        return False

    if not backtrack(0):
        return "No Solution"

    # Build result grid
    grid = []
    for r in range(nrows):
        row = []
        for c in range(ncols):
            if solution[r] & (1 << c):
                row.append('B')
            else:
                row.append(None)
        grid.append(row)

    return grid

if __name__ == "__main__":
    print(solve(OBSERVATION))

