    # For each row r: sum of col_weights[c] for black cells in row r = row_sums[r]
    # For each col c: sum of row_weights[r] for black cells in col c = col_sums[c]

    # We'll use constraint propagation + backtracking
    # State: for each cell, possible values {0, 1}
    # We process row by row, for each row finding all subsets of columns whose col_weights sum to row_sum[r]

    # First, enumerate valid row configurations
    def get_row_configs(row_idx):
        target = row_sums[row_idx]
        configs = []
        # Find all subsets of columns where sum of col_weights = target
        def backtrack(col, current_sum, chosen):
            if current_sum == target:
                configs.append(tuple(chosen))
                # Can still add cols with weight 0
                if col < num_cols and col_weights[col] == 0:
                    backtrack(col + 1, current_sum, chosen + [col])
                    backtrack(col + 1, current_sum, chosen)
                elif col < num_cols:
                    # remaining weights are all positive, so adding more would exceed
                    # but we need to check if we can skip remaining
                    # Actually we already have target met, just enumerate skipping rest
                    pass
