            remaining = sum(col_weights[c] for c in range(col, num_cols))
            if current_sum + remaining < target:
                return
            if current_sum > target:
                return
            # Include col
            if current_sum + col_weights[col] <= target:
                backtrack(col + 1, current_sum + col_weights[col], chosen + [col])
            # Exclude col
            backtrack(col + 1, current_sum, chosen)

        backtrack(0, 0, [])
        return configs

    all_row_configs = []
    for r in range(num_rows):
        configs = get_row_configs(r)
        # Convert to bitmask or set representation
        config_sets = []
        for cfg in configs:
            s = set(cfg)
            config_sets.append(s)
        all_row_configs.append(config_sets)

    # Now backtrack row by row, tracking column sums
    col_remaining_capacity = list(col_sums)  # how much more each column needs
    solution = [None] * num_rows

    def backtrack(row, col_used):
        if row == num_rows:
            # Check all column sums are met
            return all(v == 0 for v in col_used)

        rw = row_weights[row]
        remaining_row_weight_sum = sum(row_weights[r] for r in range(row + 1, num_rows))

        for config in all_row_configs[row]:
            # Check if placing blacks in these columns is feasible
            valid = True
            for c in config:
                if col_used[c] - rw < 0:
                    valid = False
                    break
            if not valid:
