                    # but also doesn't hurt. However, we should only place if needed for row target.
                    available.append(j)
                elif remaining_col[j] >= rw:
                    available.append(j)

            # Find subsets of available columns with col_weights summing to target
            results = []

            def find_subsets(idx, current_sum, chosen):
