    def find_subsets(weights, target):
        """Find all subsets of indices whose weights sum to target."""
        n = len(weights)
        results = []
        # Use bitmask for small n
        for mask in range(1 << n):
            s = 0
            for i in range(n):
                if mask & (1 << i):
                    s += weights[i]
            if s == target:
                results.append(mask)
        return results

