    # Row constraint: sum of col_weights[j] for black cells in row i = row_sums[i]
    # Col constraint: sum of row_weights[i] for black cells in col j = col_sums[j]

    # We'll use constraint propagation + backtracking
    # State: for each cell, possible values {0, 1}
    # We track remaining row sums and column sums

    grid = [[None]*ncols for _ in range(nrows)]

