OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, None, 6], [None, None, None, None, 5], [None, 7, None, None, None]]}

def solve(observation):
    data = observation['data']
    N = len(data)

    # Cell states: 0 = unknown, 1 = white, -1 = black
    grid = [[0]*N for _ in range(N)]
    clues = {}

    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                clues[(r,c)] = data[r][c]
                grid[r][c] = 1  # clue cells are always white

    def get_visible_cells(grid, r, c):
        """Get all cells visible from (r,c) including itself, given current grid state.
        Returns (definite_white, possible_cells) where possible includes unknowns."""
        visible_white = [(r,c)]
        visible_unknown = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < N and 0 <= nc < N:
                if grid[nr][nc] == -1:  # black, stop
                    break
                elif grid[nr][nc] == 1:  # white
                    visible_white.append((nr,nc))
                else:  # unknown
                    visible_unknown.append((nr,nc))
                nr += dr
                nc += dc
        return visible_white, visible_unknown

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Rule: check each clue
            for (r,c), val in clues.items():
                whites, unknowns = get_visible_cells(grid, r, c)
                # If whites already exceed val, contradiction
                if len(whites) > val:
                    return False
                # If whites == val, all unknowns in line of sight must be black
                if len(whites) == val:
                    for ur, uc in unknowns:
                        if grid[ur][uc] == 0:
                            grid[ur][uc] = -1
                            changed = True
                # If whites + unknowns == val, all unknowns must be white
                elif len(whites) + len(unknowns) == val:
                    for ur, uc in unknowns:
                        if grid[ur][uc] == 0:
                            grid[ur][uc] = 1
                            changed = True
                # If whites + unknowns < val, contradiction
                elif len(whites) + len(unknowns) < val:
                    return False

            # Rule: black cells cannot be adjacent
            for r in range(N):
                for c in range(N):
