                    numbered_cells[(r, c)] = val

    # For each white cell, compute which other white cells it illuminates (including itself along row/col)
    # A bulb at (r,c) illuminates all white cells in its row and column until blocked by a black cell

    def cells_illuminated_by(r, c):
