            if nr >= N:
                break
            if (nr, c) in black_cells:
                break
            result.add((nr, c))
        # Left
        for dc in range(-1, -N, -1):
            nc = c + dc
            if nc < 0:
                break
            if (r, nc) in black_cells:
                break
            result.add((r, nc))
        # Right
        for dc in range(1, N):
            nc = c + dc
            if nc >= N:
                break
            if (r, nc) in black_cells:
                break
            result.add((r, nc))
        return result

    # Precompute illumination sets
    illum = {}
    for cell in white_cells:
        illum[cell] = cells_illuminated_by(cell[0], cell[1])

    # For each white cell, compute which other white cells can "see" it (i.e., would conflict if both are bulbs)
    # Two bulbs conflict if one is in the illumination set of the other
    # This is symmetric: if A illuminates B, then B illuminates A

    # For each numbered black cell, find its white neighbors
    def white_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N and (nr, nc) in white_cells:
                neighbors.append((nr, nc))
        return neighbors

    num_neighbors = {}
    for nc_pos, num in numbered_cells.items():
        num_neighbors[nc_pos] = white_neighbors(nc_pos[0], nc_pos[1])

