            for nc_pos, num in numbered_cells.items():
                neighbors = num_neighbors[nc_pos]
                bulb_count = sum(1 for n in neighbors if state.get(n) == BULB)
                unknown_count = sum(1 for n in neighbors if state.get(n) == UNKNOWN)
                no_bulb_count = sum(1 for n in neighbors if state.get(n) == NO_BULB)

                if bulb_count > num:
                    return False
                if bulb_count + unknown_count < num:
                    return False

                # If we already have enough bulbs, mark remaining unknowns as NO_BULB
                if bulb_count == num:
                    for n in neighbors:
                        if state.get(n) == UNKNOWN:
                            state[n] = NO_BULB
                            changed = True

