                illuminated = False
                for other in illum[cell]:
                    if other != cell and state[other] == BULB:
                        illuminated = True
                        break
                if state[cell] == BULB:
                    illuminated = True

                if not illuminated:
                    # Find cells that could illuminate this cell (including itself if UNKNOWN)
                    possible = []
                    for other in illum[cell]:
                        if state[other] == UNKNOWN:
                            possible.append(other)

                    if len(possible) == 0:
                        return False  # Cell can never be illuminated
                    if len(possible) == 1:
                        state[possible[0]] = BULB
