        """Pick the best cell to branch on - use most constrained heuristic."""
        best = None
        best_score = float('inf')
        for cell in white_cells:
            if state[cell] == UNKNOWN:
                # Score: number of unknown cells that can see this cell
                score = sum(1 for other in illum[cell] if state[other] == UNKNOWN)
                if score < best_score:
