            return None

        cell = pick_branch_cell(state)
        if cell is None:
            return None

        # Try BULB first
        for val in [BULB, NO_BULB]:
            new_state = dict(state)
            new_state[cell] = val
            result = solve_recursive(new_state)
            if result is not None:
                return result

        return None

    result = solve_recursive(state)

    if result is None:
        return "No Solution"

    # Build answer grid
    answer = [[None]*N for _ in range(N)]
    for (r, c), val in result.items():
        if val == BULB:
            answer[r][c] = 'B'

    return answer

