    # L, I, T, S tetrominoes with all rotations/reflections
    def normalize(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        normalized = tuple(sorted((r - min_r, c - min_c) for r, c in cells))
        return normalized

    def all_rotations_reflections(cells):
        results = set()
        current = list(cells)
        for _ in range(4):
            results.add(normalize(current))
            current = [(-c, r) for r, c in current]  # rotate 90
        current = [(r, -c) for r, c in cells]  # reflect
        for _ in range(4):
            results.add(normalize(current))
            current = [(-c, r) for r, c in current]
