    # Represent edges as frozensets of two nodes
    # For efficiency, represent each edge by a canonical tuple

    def neighbors(r, c):
        result = []
        if r > 0: result.append((r-1, c))
        if r < N-1: result.append((r+1, c))
        if c > 0: result.append((r, c-1))
        if c < N-1: result.append((r, c+1))
        return result

