            if data[r][c] is not None:
                clues[(r,c)] = data[r][c]

    def other_node(edge, node):
        a, b = edge
        return b if a == node else a

    def get_direction(node, edge):
        """Return direction vector from node through edge"""
        other = other_node(edge, node)
        return (other[0] - node[0], other[1] - node[1])

    def are_collinear(edge1, edge2, node):
        """Check if two edges at a node form a straight line"""
        d1 = get_direction(node, edge1)
        d2 = get_direction(node, edge2)
