    def extract_loop(edge_state):
        """Extract the loop as ordered list of points"""
        adj = {}
        for e, s in edge_state.items():
            if s == 1:
                p1, p2 = e
                if p1 not in adj:
                    adj[p1] = []
                if p2 not in adj:
                    adj[p2] = []
                adj[p1].append(p2)
                adj[p2].append(p1)

        start = min(adj.keys())
        path = [start]
        prev = None
        current = start
        while True:
            nbs = adj[current]
            next_nodes = [n for n in nbs if n != prev]
            if not next_nodes:
                break
            nxt = next_nodes[0]
            if nxt == start:
                path.append(start)
