            return None

        # Choose edge to branch on
        e = choose_edge(edge_state)
        if e is None:
            return None

        # Try setting edge to 1 (used)
        for val in [1, -1]:
            new_state = dict(edge_state)
            new_state[e] = val
            result = backtrack(new_state)
            if result is not None:
                return result

        return None

    result = backtrack(edge_state)

    if result is None:
        return "No Solution"

    path = extract_loop(result)
    return path


