                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    # State: for each unknown cell, True=mine, False=safe, None=undecided
    state = {}
    for cell in unknowns:
        state[cell] = None

    # For each clue, track its unknown neighbors
    clue_neighbors = {}
    for (r, c), val in clues.items():
        clue_neighbors[(r, c)] = [n for n in neighbors(r, c) if n in unknowns]

    def propagate(state):
        changed = True
        while changed:
            changed = False
            for (r, c), val in clues.items():
