                    return False  # Contradiction

                if remaining == 0 and undecided:
                    for n in undecided:
                        state[n] = False
                    changed = True
                elif remaining == len(undecided) and undecided:
                    for n in undecided:
                        state[n] = True
                    changed = True

        # Final check
        for (r, c), val in clues.items():
            nbrs = clue_neighbors[(r, c)]
            mines = sum(1 for n in nbrs if state[n] is True)
            undecided = sum(1 for n in nbrs if state[n] is None)
            if mines > val or mines + undecided < val:
                return False

        return True

    def is_complete(state):
        return all(v is not None for v in state.values())

    def pick_best_undecided(state):
        # Pick undecided cell that appears in most clue constraints
        best = None
        best_score = -1
        for cell, v in state.items():
            if v is None:
                score = 0
                r, c = cell
                for nr, nc in neighbors(r, c):
                    if (nr, nc) in clues:
                        score += 1
                if score > best_score:
                    best_score = score
                    best = cell
        return best

    import copy

    def search(state):
        state = copy.copy(state)
        result = propagate(state)
        if not result:
            return None
        if is_complete(state):
            # Verify
            for (r, c), val in clues.items():
                mines = sum(1 for n in clue_neighbors[(r, c)] if state[n] is True)
                if mines != val:
                    return None
            return state

        cell = pick_best_undecided(state)
        if cell is None:
            return None

        for guess in [True, False]:
            new_state = copy.copy(state)
            new_state[cell] = guess
            sol = search(new_state)
            if sol is not None:
                return sol

        return None

    solution = search(state)

    if solution is None:
        return "No Solution"

    grid = [[None]*cols for _ in range(rows)]
    for (r, c), v in solution.items():
        if v is True:
            grid[r][c] = 'F'

    return grid

