def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # State: 0 = unknown, 1 = black, -1 = white
    grid = [[0] * cols for _ in range(rows)]

    def neighbors(r, c):
        """Return list of (row, col) in 3x3 neighborhood including (r,c)"""
        result = []
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    # Precompute neighborhoods
    nbrs = {}
    for r in range(rows):
        for c in range(cols):
            nbrs[(r, c)] = neighbors(r, c)

    # Precompute which numbered cells each cell affects
    affected_by = {}
    for r in range(rows):
        for c in range(cols):
            affected_by[(r, c)] = []

    numbered_cells = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                numbered_cells.append((r, c))
                for nr, nc in nbrs[(r, c)]:
                    affected_by[(nr, nc)].append((r, c))

    def propagate(grid):
        """Apply constraint propagation. Returns False if contradiction."""
        changed = True
        while changed:
            changed = False
            for r, c in numbered_cells:
                target = data[r][c]
                ns = nbrs[(r, c)]
                black_count = sum(1 for nr, nc in ns if grid[nr][nc] == 1)
                white_count = sum(1 for nr, nc in ns if grid[nr][nc] == -1)
                unknown = [(nr, nc) for nr, nc in ns if grid[nr][nc] == 0]
                unknown_count = len(unknown)

                # If already too many black
                if black_count > target:
                    return False
                # If not enough cells left to reach target
                if black_count + unknown_count < target:
                    return False

                # All remaining unknowns must be black
                if black_count + unknown_count == target:
                    for nr, nc in unknown:
                        grid[nr][nc] = -1  # wait, no: we need exactly target blacks
                        # Actually if black_count + unknown_count == target, all unknowns must be black
                    for nr, nc in unknown:
                        grid[nr][nc] = 1
                        changed = True

                # Already reached target, rest must be white
                if black_count == target:
                    for nr, nc in unknown:
                        grid[nr][nc] = -1
                        changed = True
        return True

    def is_valid(grid):
        """Check if current grid is consistent with all constraints."""
        for r, c in numbered_cells:
            target = data[r][c]
            ns = nbrs[(r, c)]
            black_count = sum(1 for nr, nc in ns if grid[nr][nc] == 1)
            white_count = sum(1 for nr, nc in ns if grid[nr][nc] == -1)
            unknown_count = sum(1 for nr, nc in ns if grid[nr][nc] == 0)

            if black_count > target:
                return False
            if black_count + unknown_count < target:
                return False
        return True

    def is_complete(grid):
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    return False
        return True

    def pick_cell(grid):
        """Pick the most constrained unknown cell."""
        best = None
        best_score = float('inf')
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    # Score: how many numbered constraints affect this cell
                    # and how tight those constraints are
                    score = 0
                    for nr, nc in affected_by[(r, c)]:
                        target = data[nr][nc]
                        ns = nbrs[(nr, nc)]
                        black_count = sum(1 for ar, ac in ns if grid[ar][ac] == 1)
                        unknown_count = sum(1 for ar, ac in ns if grid[ar][ac] == 0)
                        remaining = target - black_count
                        # Tighter constraint = smaller slack
                        slack = unknown_count - remaining
                        score -= (10 - slack)  # lower slack = higher priority

                    num_constraints = len(affected_by[(r, c)])
                    priority = -num_constraints * 100 + score
                    if priority < best_score:
                        best_score = priority
                        best = (r, c)
        return best

    import copy

    def solve_recursive(grid):
        if not propagate(grid):
            return None

        if is_complete(grid):
            # Final validation
            for r, c in numbered_cells:
                target = data[r][c]
                black_count = sum(1 for nr, nc in nbrs[(r, c)] if grid[nr][nc] == 1)
                if black_count != target:
                    return None
            return grid

        cell = pick_cell(grid)
        if cell is None:
            return None

        r, c = cell

        # Try black first if it seems more likely based on constraints
        for val in [1, -1]:
            new_grid = copy.deepcopy(grid)
            new_grid[r][c] = val
            if is_valid(new_grid):
                result = solve_recursive(new_grid)
                if result is not None:
                    return result

        return None

    result = solve_recursive(grid)

    if result is None:
        return "No Solution"

    # Convert to output format
    answer = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if result[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        answer.append(row)

    return answer

