        """Generate all valid arrangements for a clue in a line of given length."""
        if not clue or clue == [0]:
            return [tuple([0] * length)]

        k = len(clue)
        min_len = sum(clue) + k - 1
        if min_len > length:
            return []

        arrangements = []

        def backtrack(idx, pos, arr):
            if idx == k:
                arrangements.append(tuple(arr + [0] * (length - len(arr))))
                return
            # Earliest start for block idx is pos
            # Latest start: length - (sum of remaining blocks + gaps)
            remaining = sum(clue[idx:]) + (k - idx - 1)
            latest = length - remaining
            for start in range(pos, latest + 1):
                new_arr = arr + [0] * (start - len(arr)) + [1] * clue[idx]
                next_pos = start + clue[idx] + 1  # +1 for mandatory gap
                backtrack(idx + 1, next_pos, new_arr)

        backtrack(0, 0, [])
        return arrangements

