    # For a clue at (r,c) with type and number k:
    # - The loop passes through (r,c) with exactly 2 edges used
    # - For Black (B): the loop turns -> one horizontal, one vertical edge
    # - For White (W): the loop goes straight -> both edges in same axis (both horizontal or both vertical)
    # - k = sum of lengths of two straight segments from the circle

    # A "straight segment" from (r,c) in direction d extends until the loop turns or ends
    # The length is the number of edges in that segment

    # For a clue, we need to pick two directions and lengths
    # For B: one from {U,D} and one from {L,R}
    # For W: both from {U,D} or both from {L,R}

    # For direction d from (r,c), a segment of length L means edges along that direction
    # from (r,c) for L steps are all used, and at each intermediate dot, the two edges
    # along this direction are the only used edges (degree 2, straight through)

    # Let's think about this differently using constraint propagation on edges

    # State: for each edge, 0=unknown, 1=used, -1=excluded
    # Constraints:
    # 1. Each dot has exactly 0 or 2 used edges (loop constraint)
    # 2. Clue dots must have exactly 2 used edges with specific properties
    # 3. The used edges form a single closed loop

    # We'll use constraint propagation + backtracking

    import copy

    # edge_state: list of states
    UNKNOWN = 0
    USED = 1
    EXCLUDED = -1

    class SolverState:
        def __init__(self):
            self.edge_state = [UNKNOWN] * num_edges
            self.dot_used_count = {}
            self.dot_excluded_count = {}
            self.dot_total = {}
            for dot in dot_edges:
                self.dot_used_count[dot] = 0
                self.dot_excluded_count[dot] = 0
                self.dot_total[dot] = len(dot_edges[dot])

        def copy(self):
            s = SolverState.__new__(SolverState)
            s.edge_state = self.edge_state[:]
            s.dot_used_count = dict(self.dot_used_count)
            s.dot_excluded_count = dict(self.dot_excluded_count)
            s.dot_total = self.dot_total  # shared, immutable
            return s

        def set_edge(self, eid, val):
            """Set edge to val (USED or EXCLUDED). Returns False if contradiction."""
            if self.edge_state[eid] == val:
                return True
            if self.edge_state[eid] != UNKNOWN:
                return False  # contradiction
            self.edge_state[eid] = val
            d1, d2 = edge_list[eid]
            if val == USED:
                self.dot_used_count[d1] += 1
                self.dot_excluded_count[d1]  # no change
                self.dot_used_count[d2] += 1
                # Check: used count can't exceed 2
                if self.dot_used_count[d1] > 2 or self.dot_used_count[d2] > 2:
                    return False
            else:  # EXCLUDED
                self.dot_excluded_count[d1] += 1
                self.dot_excluded_count[d2] += 1
            return True

    def propagate(state):
        """Propagate constraints. Returns False if contradiction."""
        changed = True
        while changed:
            changed = False
            for dot in dot_edges:
                used = state.dot_used_count[dot]
                excl = state.dot_excluded_count[dot]
                total = state.dot_total[dot]
                unknown = total - used - excl

                is_clue = dot in clues

                if used > 2:
                    return False
                if used + unknown < 0:
                    return False

                if is_clue:
                    # Must have exactly 2
                    if used > 2:
                        return False
                    if used + unknown < 2:
                        return False
                    if used == 2 and unknown > 0:
                        # Exclude remaining
                        for eid in dot_edges[dot]:
                            if state.edge_state[eid] == UNKNOWN:
                                if not state.set_edge(eid, EXCLUDED):
                                    return False
                                changed = True
                    elif unknown == 2 - used and unknown > 0:
                        # Must use remaining
                        for eid in dot_edges[dot]:
                            if state.edge_state[eid] == UNKNOWN:
                                if not state.set_edge(eid, USED):
                                    return False
                                changed = True
                else:
                    # Non-clue dot: 0 or 2 used edges
                    if used > 2:
                        return False
                    if used == 2 and unknown > 0:
