                            if state.edge_state[eid] == UNKNOWN:
                                if not state.set_edge(eid, EXCLUDED):
                                    return False
                                changed = True
                    elif used == 1:
                        if unknown == 0:
                            return False  # need exactly 0 or 2, have 1
                        if unknown == 1:
                            # Must use the remaining one
                            for eid in dot_edges[dot]:
                                if state.edge_state[eid] == UNKNOWN:
                                    if not state.set_edge(eid, USED):
                                        return False
                                    changed = True
                    elif used == 0:
                        if unknown == 1:
                            # Can't reach 2, so exclude
                            for eid in dot_edges[dot]:
                                if state.edge_state[eid] == UNKNOWN:
                                    if not state.set_edge(eid, EXCLUDED):
                                        return False
                                    changed = True
                        elif unknown == 0:
                            pass  # 0 used, fine

            # Clue direction constraints
            for dot, (ctype, cnum) in clues.items():
                r, c = dot
                dirs = dot_dir_edges[dot]

                used_dirs = []
                excl_dirs = []
                unk_dirs = []
                for dname, eid in dirs.items():
                    if state.edge_state[eid] == USED:
                        used_dirs.append(dname)
                    elif state.edge_state[eid] == EXCLUDED:
                        excl_dirs.append(dname)
                    else:
                        unk_dirs.append(dname)

                if len(used_dirs) == 2:
                    d1, d2 = used_dirs
                    if ctype == 'B':
                        # Must turn: one H, one V
                        h = {'L', 'R'}
                        v = {'U', 'D'}
                        if (d1 in h and d2 in h) or (d1 in v and d2 in v):
                            return False
                    else:  # W
                        # Must go straight: same axis
                        h = {'L', 'R'}
                        v = {'U', 'D'}
                        if not ((d1 in h and d2 in h) or (d1 in v and d2 in v)):
                            return False

                if len(used_dirs) == 1:
                    ud = used_dirs[0]
                    if ctype == 'B':
                        # Turn: the other must be perpendicular
                        h = {'L', 'R'}
                        v = {'U', 'D'}
                        if ud in h:
                            # Other must be in v
                            # Exclude any unknown in h
                            for dname in unk_dirs:
                                if dname in h:
                                    eid = dirs[dname]
                                    if not state.set_edge(eid, EXCLUDED):
                                        return False
                                    changed = True
                        else:
                            for dname in unk_dirs:
                                if dname in v:
                                    eid = dirs[dname]
                                    if not state.set_edge(eid, EXCLUDED):
                                        return False
                                    changed = True
                    else:  # W straight
                        h = {'L', 'R'}
                        v = {'U', 'D'}
                        if ud in h:
                            # Other must be in h
                            for dname in unk_dirs:
                                if dname in v:
                                    eid = dirs[dname]
                                    if not state.set_edge(eid, EXCLUDED):
                                        return False
                                    changed = True
                        else:
                            for dname in unk_dirs:
                                if dname in h:
                                    eid = dirs[dname]
                                    if not state.set_edge(eid, EXCLUDED):
                                        return False
                                    changed = True

            # Early loop detection: check no small loops unless all clue/used dots are included
            # (deferred to validation)

        return True

    def get_segments_from_dot(state, dot, direction):
        """
        Get the length of the straight segment from dot in given direction.
        Returns (min_len, max_len) considering unknowns.
        direction is (dr, dc)
        """
        dr, dc = direction
        r, c = dot
        length = 0
        cr, cc = r + dr, c + dc
        while 0 <= cr < rows and 0 <= cc < cols:
            ek = edge_key((cr - dr, cc - dc), (cr, cc))
            eid = all_edges[ek]
            if state.edge_state[eid] == USED:
                length += 1
                cr += dr
                cc += dc
            elif state.edge_state[eid] == EXCLUDED:
                break
            else:
                break
        return length

    def check_clue_feasibility(state):
        """Check if clue constraints are still feasible."""
        for dot, (ctype, cnum) in clues.items():
            r, c = dot
            dirs_map = dot_dir_edges[dot]

            used_dirs = []
            for dname, eid in dirs_map.items():
                if state.edge_state[eid] == USED:
                    used_dirs.append(dname)

            if len(used_dirs) < 2:
                continue  # not fully determined yet

            if len(used_dirs) != 2:
                return False

            d1, d2 = used_dirs

            # Compute segment lengths
            dir_vectors = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

            def segment_length(dot, dname):
                dr, dc = dir_vectors[dname]
                cr, cc = dot[0] + dr, dot[1] + dc
                length = 0
                while 0 <= cr < rows and 0 <= cc < cols:
                    ek = edge_key((cr - dr, cc - dc), (cr, cc))
                    eid = all_edges[ek]
                    if state.edge_state[eid] == USED:
                        length += 1
                        # Check intermediate dot goes straight
                        cr += dr
                        cc += dc
                    else:
                        break
                return length

            # For fully determined edges, check segment sum
            # But edges might not all be determined yet
            # We need min/max possible segment lengths
            def segment_range(dot, dname):
                dr, dc = dir_vectors[dname]
                cr, cc = dot[0] + dr, dot[1] + dc
                min_len = 0
                max_len = 0
                certain = True
                while 0 <= cr < rows and 0 <= cc < cols:
                    ek = edge_key((cr - dr, cc - dc), (cr, cc))
                    eid = all_edges[ek]
                    if state.edge_state[eid] == USED:
                        min_len += 1
                        max_len += 1
                        cr += dr
                        cc += dc
                    elif state.edge_state[eid] == EXCLUDED:
                        break
                    else:
                        # Unknown: could be used or not
                        max_len += 1
                        certain = False
                        cr += dr
                        cc += dc
                return min_len, max_len

            min1, max1 = segment_range(dot, d1)
            min2, max2 = segment_range(dot, d2)

            # Each segment must be >= 1
            min1 = max(min1, 1)
            min2 = max(min2, 1)

            if min1 + min2 > cnum:
                return False
            if max1 + max2 < cnum:
                return False

        return True

    def check_single_loop(state):
        """Check if used edges form a single closed loop."""
        # Build adjacency from used edges
        adj = {}
        for eid in range(num_edges):
            if state.edge_state[eid] == USED:
                d1, d2 = edge_list[eid]
                if d1 not in adj:
                    adj[d1] = []
                if d2 not in adj:
                    adj[d2] = []
                adj[d1].append(d2)
                adj[d2].append(d1)

        if not adj:
            return False

        # Check all degrees are 2
        for dot, neighbors in adj.items():
            if len(neighbors) != 2:
                return False

        # Check connectivity
        start = next(iter(adj))
        visited = {start}
        stack = [start]
        while stack:
            node = stack.pop()
            for nb in adj[node]:
                if nb not in visited:
                    visited.add(nb)
                    stack.append(nb)

        if len(visited) != len(adj):
            return False

        # Check all clues are in the loop
        for dot in clues:
            if dot not in adj:
