        return True

    def check_clue_segments_exact(state):
        """Check exact segment lengths for all clues."""
        dir_vectors = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

        for dot, (ctype, cnum) in clues.items():
            dirs_map = dot_dir_edges[dot]
            used_dirs = []
            for dname, eid in dirs_map.items():
                if state.edge_state[eid] == USED:
                    used_dirs.append(dname)

            if len(used_dirs) != 2:
                return False

            d1, d2 = used_dirs

            # Check turn/straight
            h = {'L', 'R'}
            v = {'U', 'D'}
            if ctype == 'B':
                if (d1 in h and d2 in h) or (d1 in v and d2 in v):
                    return False
            else:
                if not ((d1 in h and d2 in h) or (d1 in v and d2 in v)):
                    return False

            def segment_length(dot, dname):
                dr, dc = dir_vectors[dname]
                cr, cc = dot[0] + dr, dot[1] + dc
                length = 0
                while 0 <= cr < rows and 0 <= cc < cols:
                    ek = edge_key((cr - dr, cc - dc), (cr, cc))
                    eid = all_edges[ek]
                    if state.edge_state[eid] == USED:
                        length += 1
                        cr += dr
                        cc += dc
                    else:
                        break
                return length

            l1 = segment_length(dot, d1)
            l2 = segment_length(dot, d2)

            if l1 + l2 != cnum:
                return False

        return True

    def extract_loop(state):
        """Extract the loop path."""
        adj = {}
        for eid in range(num_edges):
            if state.edge_state[eid] == USED:
                d1, d2 = edge_list[eid]
                if d1 not in adj:
                    adj[d1] = []
                if d2 not in adj:
                    adj[d2] = []
                adj[d1].append(d2)
                adj[d2].append(d1)

        start = next(iter(adj))
        path = [start]
        prev = None
        curr = start
        while True:
            neighbors = adj[curr]
            nxt = None
            for nb in neighbors:
                if nb != prev:
                    nxt = nb
                    break
            if nxt == start:
                path.append(start)
                break
            path.append(nxt)
            prev = curr
            curr = nxt

        return path

    def has_premature_loop(state):
        """Check if there's a small loop among used edges that doesn't include all clue dots."""
        adj = {}
        for eid in range(num_edges):
            if state.edge_state[eid] == USED:
                d1, d2 = edge_list[eid]
                if d1 not in adj:
                    adj[d1] = []
                if d2 not in adj:
                    adj[d2] = []
                adj[d1].append(d2)
                adj[d2].append(d1)

        if not adj:
            return False

        # Find connected components where all nodes have degree 2 (closed loops)
        visited = set()
        for start_dot in adj:
            if start_dot in visited:
                continue
            if len(adj[start_dot]) != 2:
                # Not a closed loop component (has open ends)
                component = set()
                stack = [start_dot]
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    component.add(node)
                    for nb in adj[node]:
                        if nb not in visited:
                            stack.append(nb)
                continue

            # Check if this component is a closed loop
            component = set()
            stack = [start_dot]
            all_deg2 = True
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                component.add(node)
                if len(adj.get(node, [])) != 2:
                    all_deg2 = False
                for nb in adj.get(node, []):
                    if nb not in visited:
                        stack.append(nb)

            if all_deg2 and len(component) > 0:
                # This is a closed loop. Check if there are still unknown edges
                # that could extend it, or if all clues are covered
                has_unknown_connection = False
                for node in component:
                    for eid in dot_edges[node]:
                        if state.edge_state[eid] == UNKNOWN:
                            # There's still an unknown edge touching this loop
                            # But since all nodes have degree 2, they can't accept more edges
                            pass

                # If any clue is not in this component, and there are no more unknown edges
                # to potentially form another path, this is premature
                # Actually, if all nodes in component have degree 2, the loop is closed
                # Check if all clues are in this component
                all_clues_in = all(cd in component for cd in clues)
                if not all_clues_in:
                    return True

                # Also check if there are used edges outside this component
                # (would mean multiple loops)
                all_used_dots = set(adj.keys())
                if all_used_dots != component:
                    return True

        return False

    # Main solving with backtracking
    def solve_bt(state):
        if not propagate(state):
            return None

        if not check_clue_feasibility(state):
            return None

        if has_premature_loop(state):
            return None

        # Check if all edges are determined
        unknowns = []
        for eid in range(num_edges):
            if state.edge_state[eid] == UNKNOWN:
                unknowns.append(eid)

        if not unknowns:
            # All determined, check solution
            if check_single_loop(state) and check_clue_segments_exact(state):
                return state
            return None

        # Choose an edge to branch on - prefer edges near clues
        best_eid = None
        best_score = -1
        for eid in unknowns:
            d1, d2 = edge_list[eid]
            score = 0
            if d1 in clues:
                score += 10
            if d2 in clues:
                score += 10
            # Prefer edges where dots have fewer unknowns (more constrained)
            unk1 = state.dot_total[d1] - state.dot_used_count[d1] - state.dot_excluded_count[d1]
            unk2 = state.dot_total[d2] - state.dot_used_count[d2] - state.dot_excluded_count[d2]
            score += (8 - unk1) + (8 - unk2)
            if score > best_score:
                best_score = score
                best_eid = eid

        eid = best_eid

        # Try USED first, then EXCLUDED
        for val in [USED, EXCLUDED]:
            new_state = state.copy()
            if new_state.set_edge(eid, val):
                result = solve_bt(new_state)
                if result is not None:
                    return result

        return None

    # Initialize state
    init_state = SolverState()

    result = solve_bt(init_state)

    if result is None:
        return "No Solution"

    path = extract_loop(result)
    return path

