def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # Parse clues
    clues = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                token = data[r][c]
                ctype = token[0]  # 'B' or 'W'
                cval = int(token[1:])
