    # Edges: between adjacent dots (horizontal or vertical)
    # Represent edge as frozenset of two points, but for efficiency use canonical tuple
    # Edge: ((r1,c1),(r2,c2)) where (r1,c1) < (r2,c2)

    def edge_key(p1, p2):
        if p1 < p2:
            return (p1, p2)
        return (p2, p1)

    def neighbors(r, c):
        result = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    all_edges = set()
    for r in range(rows):
        for c in range(cols):
            if c+1 < cols:
                all_edges.add(((r,c),(r,c+1)))
            if r+1 < rows:
                all_edges.add(((r,c),(r+1,c)))

    # State for each edge: True (in loop), False (not in loop), None (unknown)
    edge_state = {}
    for e in all_edges:
