        dot_edges[p1].append(e)
        dot_edges[p2].append(e)

    def get_edge(p1, p2):
        return edge_key(p1, p2)

    def direction(p1, p2):
        """Return direction from p1 to p2"""
        dr = p2[0] - p1[0]
        dc = p2[1] - p1[1]
        return (dr, dc)

    def opposite_dir(d):
        return (-d[0], -d[1])

    # For constraint propagation, we need to track:
    # - For each dot: exactly 0 or 2 edges must be True (loop constraint)
    # - For clue dots: must have exactly 2 edges, with specific constraints

    # Let's use a more sophisticated approach with constraint propagation
    # Edge states: 1 = in loop, 0 = not in loop, -1 = unknown

    estate = {}
