            else:
                unk.append(e)
        return tc, fc, len(unk), unk

    def propagate(estate):
        """Propagate constraints. Returns False on contradiction."""
        queue = list(dot_edges.keys())
        visited_rounds = 0

        while queue:
            dot = queue.pop(0)
            tc, fc, uc, unk = count_edges(dot, estate)

            is_clue = dot in clues

            # Basic loop constraint: each dot has 0 or 2 true edges
