    # Edge representation: frozenset of two dots
    # For efficiency, use a dict mapping each dot to its possible edges

    # Directions: up, down, left, right
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def neighbors(r, c):
        result = []
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

