    # Non-clue dots may have degree 0 or 2

    def get_dir(d1, d2):
        """Return direction from d1 to d2"""
        return (d2[0] - d1[0], d2[1] - d1[1])

    def are_opposite(dir1, dir2):
        return dir1[0] + dir2[0] == 0 and dir1[1] + dir2[1] == 0

    def are_same_line(d1, center, d2):
        """Check if d1-center-d2 form a straight line"""
        dir1 = get_dir(center, d1)
        dir2 = get_dir(center, d2)
        return are_opposite(dir1, dir2)

