                        seg1 = measure_segment(state, dot, d1)
                        seg2 = measure_segment(state, dot, d2)

                        if seg1 is not None and seg2 is not None:
                            if seg1 + seg2 != num:
                                return False
                        elif seg1 is not None:
                            if seg1 >= num:
                                return False
                        elif seg2 is not None:
                            if seg2 >= num:
                                return False

            # Premature loop detection: check if used edges form a loop 
            # that doesn't include all clue dots or all used dots
            # (We'll do this check less frequently)

        return True

    def measure_segment(state, dot, direction):
        """
        Measure the length of a straight segment starting from dot going in direction.
        Returns the length if the segment is fully determined (all edges used until a turn/end),
        or None if there are still unknown edges along the way.
        Returns the minimum guaranteed length if partially determined.
        Actually, let's return the exact length if fully determined, else None.
        """
        length = 0
        current = dot
        while True:
            nr, nc = current[0] + direction[0], current[1] + direction[1]
            if not (0 <= nr < rows and 0 <= nc < cols):
                return length
            next_dot = (nr, nc)
            e = edge_id(current, next_dot)
            if state.edge_state[e] == 1:
                length += 1
                current = next_dot
            elif state.edge_state[e] == -1:
                return length
            else:
                return None  # unknown

    def find_components(state):
        """Find connected components of used edges."""
        adj = {}
        for e, val in state.edge_state.items():
            if val == 1:
                d1, d2 = e
                if d1 not in adj:
                    adj[d1] = []
                if d2 not in adj:
                    adj[d2] = []
                adj[d1].append(d2)
                adj[d2].append(d1)

        visited = set()
        components = []
        for dot in adj:
            if dot not in visited:
                comp = set()
                stack = [dot]
                while stack:
                    d = stack.pop()
                    if d in visited:
                        continue
                    visited.add(d)
                    comp.add(d)
                    for n in adj[d]:
                        if n not in visited:
                            stack.append(n)
                components.append(comp)
        return components, adj

    def check_no_premature_loop(state):
        """Check that there's no closed loop that doesn't include all required dots."""
        components, adj = find_components(state)

        # Count total used edges
        total_used = sum(1 for e in state.edge_state.values() if e == 1)
        total_unknown = sum(1 for e in state.edge_state.values() if e == 0)

        for comp in components:
            # Check if this component forms a closed loop
            is_loop = all(len(adj[d]) == 2 for d in comp)
            if is_loop:
                # Check if all clue dots are in this component
                all_clues_in = all(c in comp for c in clues)
                if not all_clues_in:
                    return False
                # If there are still unknown edges, other dots might need to be connected
                if total_unknown > 0:
                    # There might be dots that still need to be connected
                    # Actually if we have a complete loop but unknowns remain,
                    # the unknowns should all be excluded
                    pass
                # If this is the only component and all clues are in, it might be valid

        # Check for small loops that don't contain all clues
        for comp in components:
            is_loop = all(len(adj.get(d, [])) == 2 for d in comp if d in adj)
            if is_loop and len(comp) > 0:
                if not all(c in comp for c in clues):
                    return False

        # Check connectivity: all dots with used edges should be in one component
        if len(components) > 1:
            # Multiple components - check if they can still be connected
            # For now, just check no component is a closed loop
            for comp in components:
                all_deg_2 = all(len(adj.get(d, [])) == 2 for d in comp)
                if all_deg_2:
                    return False  # closed sub-loop

        return True

    def is_complete(state):
        """Check if the solution is complete."""
        # All clue dots must have degree 2
        for dot in clues:
            if state.dot_used[dot] != 2:
                return False

        # All dots with any used edge must have degree exactly 2
        for dot in dot_edges:
            if state.dot_used[dot] != 0 and state.dot_used[dot] != 2:
                return False

        # Must form a single loop
        components, adj = find_components(state)
        if len(components) != 1:
            return False

        # All dots in the component must have degree 2
        comp = components[0]
        for d in comp:
            if len(adj[d]) != 2:
                return False

        # All clues must be in the loop
        for c in clues:
            if c not in comp:
                return False

        # Verify all clue constraints
        for dot, (color, num) in clues.items():
            used = [e for e in dot_edges[dot] if state.edge_state[e] == 1]
            if len(used) != 2:
                return False

            o1 = other_end(used[0], dot)
            o2 = other_end(used[1], dot)

            d1 = get_dir(dot, o1)
            d2 = get_dir(dot, o2)

            if color == 'W':
                if not are_opposite(d1, d2):
                    return False
            else:  # B
                if are_opposite(d1, d2):
                    return False

            seg1 = measure_segment(state, dot, d1)
            seg2 = measure_segment(state, dot, d2)

            if seg1 is None or seg2 is None:
                return False
            if seg1 + seg2 != num:
                return False

        return True

    def extract_loop(state):
        """Extract the loop as ordered list of dots."""
        components, adj = find_components(state)
        if len(components) != 1:
            return None

        comp = components[0]
        start = min(comp)
        path = [start]
        prev = None
        current = start

        while True:
            nexts = [n for n in adj[current] if n != prev]
            if not nexts:
                break
            next_dot = nexts[0]
            if next_dot == start:
                path.append(start)
                break
            path.append(next_dot)
            prev = current
            current = next_dot

        return path

    def get_segment_constraints(state, dot, color, num):
        """
        For a clue dot, get possible direction pairs and check segment length constraints.
        Returns list of possible (edge1, edge2) pairs, or None if already determined.
        """
        used = state.get_used_edges(dot)
        unknown = state.get_unknown_edges(dot)

        if len(used) == 2:
            return None  # already determined

        possible_pairs = []
        candidates = used + unknown

        for i in range(len(candidates)):
            for j in range(i + 1, len(candidates)):
                e1, e2 = candidates[i], candidates[j]
                o1 = other_end(e1, dot)
                o2 = other_end(e2, dot)
                d1 = get_dir(dot, o1)
                d2 = get_dir(dot, o2)

                if color == 'W' and not are_opposite(d1, d2):
                    continue
                if color == 'B' and are_opposite(d1, d2):
                    continue

                # Check if both edges can be used
                if state.edge_state[e1] == -1 or state.edge_state[e2] == -1:
                    continue

                possible_pairs.append((e1, e2))

        return possible_pairs

    def solve_backtrack(state, depth=0):
        if not propagate(state):
            return None

        if not check_no_premature_loop(state):
