        # Find the best variable to branch on
        # Prefer clue dots with fewest options
        best_dot = None
        best_pairs = None
        best_count = float('inf')

        for dot, (color, num) in clues.items():
            if state.dot_used[dot] == 2:
                continue
            pairs = get_segment_constraints(state, dot, color, num)
            if pairs is not None:
                if len(pairs) == 0:
                    return None  # no valid configuration
                if len(pairs) < best_count:
                    best_count = len(pairs)
                    best_dot = dot
                    best_pairs = pairs

        if best_dot is not None:
            for e1, e2 in best_pairs:
                new_state = state.copy()
                ok = True
                if not new_state.set_edge(e1, 1):
                    continue
                if not new_state.set_edge(e2, 1):
                    continue
                # Exclude other edges at this dot
                for e in dot_edges[best_dot]:
                    if e != e1 and e != e2:
                        if not new_state.set_edge(e, -1):
                            ok = False
                            break
                if not ok:
                    continue

                result = solve_backtrack(new_state, depth + 1)
                if result is not None:
                    return result
            return None

        # Branch on an unknown edge
        # Find edge with most constraints
        best_edge = None
        best_score = -1

        for e, val in state.edge_state.items():
            if val == 0:
                d1, d2 = e
                score = 0
                if d1 in clues:
                    score += 10
                if d2 in clues:
                    score += 10
                score += state.dot_used[d1] + state.dot_used[d2]
                if score > best_score:
                    best_score = score
                    best_edge = e

        if best_edge is None:
            if is_complete(state):
                return state
            return None

        # Try including the edge
        for val in [1, -1]:
            new_state = state.copy()
            if new_state.set_edge(best_edge, val):
                result = solve_backtrack(new_state, depth + 1)
                if result is not None:
                    return result

        return None

    # Enhanced propagation with segment length constraints
    def propagate_enhanced(state):
        """More thorough propagation including segment lengths."""
        if not propagate(state):
            return False

        changed = True
        while changed:
