    def max_segment(state, dot, direction):
        """Maximum possible segment length in given direction."""
        length = 0
        current = dot
        while True:
            nr, nc = current[0] + direction[0], current[1] + direction[1]
            if not (0 <= nr < rows and 0 <= nc < cols):
