    def enforce_segment(state, dot, direction, needed_length):
        """Try to enforce that segment in direction has exactly needed_length."""
        # Include edges up to needed_length, exclude the one after
        current = dot
        changed = False
        for i in range(needed_length):
            nr, nc = current[0] + direction[0], current[1] + direction[1]
            if not (0 <= nr < rows and 0 <= nc < cols):
