        if 0 <= nr < rows and 0 <= nc < cols:
            next_dot = (nr, nc)
            e = edge_id(current, next_dot)
            if state.edge_state[e] == 1:
                return False  # segment too long
            if state.edge_state[e] == 0:
                if not state.set_edge(e, -1):
                    return False
                changed = True

        return changed  # True if changes made, but not False (no contradiction)

    # Override propagate in solve_backtrack to use enhanced version
