    #   cell (dr-1, dc-1) if '\' (bottom-right corner of that cell)
    #   cell (dr-1, dc) if '/' (bottom-left corner of that cell)
    #   cell (dr, dc) if '\' (top-left corner of that cell)
    #   cell (dr, dc-1) if '/' (top-right corner of that cell)

    def incident_cells(dr, dc):
        """Returns list of (cell_r, cell_c, diagonal_type) that would be incident to dot (dr,dc)"""
        result = []
        # cell (dr-1, dc-1) with '\'
        if dr-1 >= 0 and dc-1 >= 0:
            result.append((dr-1, dc-1, '\\'))
        # cell (dr-1, dc) with '/'
        if dr-1 >= 0 and dc < N:
            result.append((dr-1, dc, '/'))
        # cell (dr, dc) with '\'
        if dr < N and dc < N:
            result.append((dr, dc, '\\'))
        # cell (dr, dc-1) with '/'
        if dr < N and dc-1 >= 0:
            result.append((dr, dc-1, '/'))
        return result

    # State: grid[r][c] = None (unset), '/' or '\'
    grid = [[None]*N for _ in range(N)]

