    # Union-Find for loop detection
    class UnionFind:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.edge_count = [0] * n  # edges in each component
            self.node_count = [1] * n

        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, x, y):
            """Returns False if adding edge x-y would create a cycle"""
            rx, ry = self.find(x), self.find(y)
            if rx == ry:
                return False  # cycle!
            if self.rank[rx] < self.rank[ry]:
                rx, ry = ry, rx
            self.parent[ry] = rx
            self.node_count[rx] += self.node_count[ry]
            self.edge_count[rx] += self.edge_count[ry] + 1
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1
            return True

        def copy(self):
            uf = UnionFind(0)
            uf.parent = self.parent[:]
            uf.rank = self.rank[:]
            uf.edge_count = self.edge_count[:]
            uf.node_count = self.node_count[:]
            return uf

    # Dot index
    def dot_idx(dr, dc):
