    # Let me restart with a cleaner approach

    def solve_clean():
        # cell_val: N x N, 0 = unassigned, 1 = '\', 2 = '/'
        cell_val = [[0]*N for _ in range(N)]

        # For each cell, which dots it touches for each diagonal
