            if uf.find(idx0) == uf.find(idx1):
                return None  # would create loop

            uf.union(idx0, idx1)
            cell_val[r][c] = code
            domain[r][c] = {code}
            return [(r, c)]

        def propagate(queue, uf):
            """Process queue of recently assigned cells. Returns False on contradiction."""
            while queue:
                r, c = queue.pop()
                code = cell_val[r][c]

                # Check all 4 corner dots of this cell
                corners = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]

                for dot in corners:
