                                queue.extend(result)

            # Also check all dots for any new deductions
            changed = True
            while changed:
                changed = False
                for dr in range(N+1):
                    for dc in range(N+1):
                        if (dr, dc) not in dot_clues:
                            continue
                        clue = dot_clues[(dr, dc)]
