                                    if len(domain[cr][cc]) == 1:
                                        forced_code = next(iter(domain[cr][cc]))
                                        result = assign(cr, cc, forced_code, uf)
                                        if result is None:
                                            return False
                                        new_queue = list(result)
                                        # propagate these
                                        if not propagate(new_queue, uf):
