                                if cell_val[cr][cc] == 0 and req_code in domain[cr][cc]:
                                    result = assign(cr, cc, req_code, uf)
                                    if result is None:
                                        return False
                                    new_queue = list(result)
                                    if not propagate(new_queue, uf):
                                        return False
                                    changed = True

            return True

        def save_state(uf):
            return (
                [row[:] for row in cell_val],
                [row[:] for row in domain],  # need deep copy of sets
                uf.copy()
            )

        def save_state_full(uf):
            return (
                [row[:] for row in cell_val],
                [[s.copy() for s in row] for row in domain],
                uf.copy()
            )

        def restore_state(state):
            cv, dom, uf = state
            for r in range(N):
                for c in range(N):
                    cell_val[r][c] = cv[r][c]
                    domain[r][c] = dom[r][c].copy()
