def solve(observation):
    data = observation['data']
    N = len(data) - 1  # Grid is N x N cells, dots are (N+1) x (N+1)

    # Each cell (r, c) has a diagonal: 0 = '/', 1 = '\'
    # For cell (r, c):
    #   '\' connects dot (r, c) to dot (r+1, c+1)
