    #   cell (dr-1, dc) with '/' (slash)
    #   cell (dr, dc-1) with '/' (slash)
    #   cell (dr, dc) with '\' (backslash)

    def get_incident_cells(dr, dc):
        """Returns list of (cell_r, cell_c, diagonal_type) that touch dot (dr, dc)"""
        cells = []
        # top-left cell
