            cells.append((dr - 1, dc, 0))  # slash
        # bottom-left cell
        if dr < N and dc - 1 >= 0:
            cells.append((dr, dc - 1, 0))  # slash
        # bottom-right cell
        if dr < N and dc < N:
            cells.append((dr, dc, 1))  # backslash
        return cells

    # grid[r][c] = None (unset), 0 (slash '/'), 1 (backslash '\')
    grid = [[None] * N for _ in range(N)]

    # For each dot, precompute incident cells
    dot_incidents = {}
    for (dr, dc), clue in dot_clues.items():
        dot_incidents[(dr, dc)] = get_incident_cells(dr, dc)

