            cell_to_dots[cr][cc].append((dr, dc, dtype))

    # Union-Find for loop detection
    # Each diagonal creates an edge between two dots
    # '\' in cell (r,c): edge between (r, c) and (r+1, c+1)
    # '/' in cell (r,c): edge between (r, c+1) and (r+1, c)
    # No loops means the graph must be a forest (tree/forest)

    parent = {}
    rank = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        """Returns True if successfully united (no cycle), False if cycle detected"""
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    def init_uf():
        parent.clear()
        rank.clear()
        for dr in range(N + 1):
            for dc in range(N + 1):
                parent[(dr, dc)] = (dr, dc)
                rank[(dr, dc)] = 0

    # Use constraint propagation + backtracking
    # Domain: for each cell, set of possible values {0, 1}
    domain = [[{0, 1} for _ in range(N)] for _ in range(N)]

    def count_incident(dr, dc, grid):
        """Count current incident diagonals and possible future ones for a dot"""
        incidents = get_incident_cells(dr, dc)
        current = 0
        possible = 0
        for (cr, cc, dtype) in incidents:
            if grid[cr][cc] is not None:
                if grid[cr][cc] == dtype:
                    current += 1
            else:
                if dtype in domain[cr][cc]:
                    possible += 1
        return current, possible

    def propagate(grid, domain):
        """Constraint propagation. Returns True if consistent, False if contradiction."""
        changed = True
        while changed:
            changed = False
            # Dot constraints
            for (dr, dc), clue in dot_clues.items():
                incidents = get_incident_cells(dr, dc)
                current = 0
                unset = []
                for (cr, cc, dtype) in incidents:
                    if grid[cr][cc] is not None:
