                                val = next(iter(domain[cr][cc]))
                                grid[cr][cc] = val
                                changed = True

                elif need == can_add:
                    # All cells that can contribute must contribute
                    for (cr, cc, dtype) in unset:
                        if dtype in domain[cr][cc]:
                            # Must be dtype
                            other = 1 - dtype
                            if other in domain[cr][cc]:
                                domain[cr][cc].discard(other)
                                if len(domain[cr][cc]) == 0:
                                    return False
                                if len(domain[cr][cc]) == 1:
                                    val = next(iter(domain[cr][cc]))
                                    grid[cr][cc] = val
                                    changed = True

            # Check single-domain cells
            for r in range(N):
