    def check_loops_incremental(grid, parent_copy, rank_copy, r, c):
        """Check if adding grid[r][c] creates a loop"""
        parent.update(parent_copy)
        rank.update(rank_copy)
        if grid[r][c] == 1:
            a, b = (r, c), (r + 1, c + 1)
        else:
            a, b = (r, c + 1), (r + 1, c)
        return union(a, b)

    def copy_state(grid, domain):
        g = [row[:] for row in grid]
        d = [[ set(domain[r][c]) for c in range(N)] for r in range(N)]
        return g, d

    def backtrack(grid, domain, depth=0):
