        # Find connected components of degree-2 nodes
        # If any component forms a closed loop, it's a premature loop
        visited = set()
        for start in adj:
            if start in visited:
                continue
            if len(adj[start]) != 2:
                # degree 1 node - trace path
                visited.add(start)
                stack = [start]
                while stack:
                    node = stack.pop()
                    for nb in adj[node]:
                        if nb not in visited:
                            visited.add(nb)
                            stack.append(nb)
                continue
            # degree 2 - could be part of a loop
            component = {start}
            stack = [start]
            is_loop = True
            while stack:
                node = stack.pop()
                if len(adj.get(node, [])) != 2:
                    is_loop = False
                for nb in adj.get(node, []):
                    if nb not in component:
                        component.add(nb)
                        stack.append(nb)
            visited.update(component)
            if is_loop and len(component) >= 3:
                # All nodes in component have degree 2 -> closed loop
                # Check if there are other ON edges or unknowns
                # that could extend - but since all degree 2, no extension possible
                # If there are unknowns or other ON edges, this is premature
                other_on = any(eid for eid in on_edges 
                             if edge_endpoints[eid][0] not in component 
                             or edge_endpoints[eid][1] not in component)
                if other_on or has_unknown:
                    # Check if any dot not in this component has unknown edges
                    # Actually, if this loop is complete and there are other ON edges, fail
                    # If there are unknowns that could still be set, we need to check more carefully
                    # For safety, if there are other ON edges outside this component, fail
                    if other_on:
                        return False
                    # If all ON edges are in this component but unknowns exist,
                    # the unknowns might all be set to off - that's ok
                    # But we need to check if clue constraints can be satisfied

        return True

    def extract_loop(state):
        on_edges = [i for i in range(total_edges) if state[i] == 1]
        adj = {}
        for eid in on_edges:
            a, b = edge_endpoints[eid]
            if a not in adj:
                adj[a] = []
            adj[a].append(b)
            if b not in adj:
                adj[b] = []
            adj[b].append(a)

        start = min(adj.keys())
        path = [start]
        prev = None
        current = start
        while True:
            neighbors = adj[current]
            next_node = None
            for nb in neighbors:
                if nb != prev:
                    next_node = nb
                    break
            if next_node == start:
                path.append(start)
                break
            path.append(next_node)
            prev = current
            current = next_node

