            return None

        # Check for premature loops
        if not check_no_small_loops(state):
            return None

        # Choose edge to branch on - pick one involved in most constraints
        # Heuristic: pick edge adjacent to a clue cell with fewest unknowns
        best_edge = None
        best_score = float('inf')

        for i, j, clue, edges in clue_cells:
