                unknown_edges = [e for e in edges if state[e] == 0]
                if on_count > 0 and unknown_edges:
                    score = len(unknown_edges)
                    if score < best_score:
                        best_score = score
                        best_edge = unknown_edges[0]

            if best_edge is None:
                best_edge = unknowns[0]

        # Try ON first, then OFF
        for val in [1, -1]:
            new_state = list(state)
            new_state[best_edge] = val
            if propagate(new_state):
                result = solve_dfs(new_state)
                if result is not None:
                    return result

        return None

    result = solve_dfs(state)
    if result is None:
