        for sr, sc in placed_stars:
            if abs(sr - r) <= 1 and abs(sc - c) <= 1:
                return False
        return True

    def eliminate(candidates, placed_stars):
        """Constraint propagation: eliminate impossible candidates."""
        changed = True
        while changed:
            changed = False

            # For each row, if only one candidate left, place it
            for r in range(N):
                cols = [c for c in range(N) if candidates[r][c]]
                if len(cols) == 0:
                    # Check if star already placed in this row
                    if not any(sr == r for sr, sc in placed_stars):
                        return False
                elif len(cols) == 1 and not any(sr == r for sr, sc in placed_stars):
                    # Must place star here
                    return None  # Signal to place this star in search

            # For each column, if only one candidate left, place it
            for c in range(N):
                rows = [r for r in range(N) if candidates[r][c]]
                if len(rows) == 0:
                    if not any(sc == c for sr, sc in placed_stars):
                        return False

