                avail = [(r, c) for r, c in cells if candidates[r][c]]
                if len(avail) == 0:
                    if not any((sr, sc) in cells for sr, sc in placed_stars):
                        return False

        return True

    # Backtracking search row by row
    def search(row, placed_stars, used_cols, used_regions):
        if row == N:
            if len(placed_stars) == N:
                return list(placed_stars)
            return None

        # Already placed a star in this row? (shouldn't happen with row-by-row)
        # Try each column in this row
        for c in range(N):
            if c in used_cols:
                continue
            rid = data[row][c]
            if rid in used_regions:
                continue
            # Check adjacency with placed stars
            if not is_valid_placement(placed_stars, row, c):
                continue

            # Pruning: check remaining rows/cols/regions can be satisfied
            new_used_cols = used_cols | {c}
            new_used_regions = used_regions | {rid}

            # Forward check: for each remaining row, is there at least one valid column?
            feasible = True
            for future_row in range(row + 1, N):
                has_option = False
                for fc in range(N):
                    if fc in new_used_cols:
                        continue
                    frid = data[future_row][fc]
                    if frid in new_used_regions:
                        continue
                    # Check adjacency with current placement
                    if abs(future_row - row) <= 1 and abs(fc - c) <= 1:
                        continue
                    # Check adjacency with all placed stars
                    adj_ok = True
                    for sr, sc in placed_stars:
                        if abs(future_row - sr) <= 1 and abs(fc - sc) <= 1:
                            adj_ok = False
                            break
                    if adj_ok:
                        has_option = True
                        break
                if not has_option:
                    feasible = False
                    break

            if not feasible:
                continue

            placed_stars.append((row, c))
            result = search(row + 1, placed_stars, new_used_cols, new_used_regions)
            if result is not None:
                return result
            placed_stars.pop()

        return None

    solution = search(0, [], set(), set())

    if solution is None:
        return "No Solution"

    grid = [[None] * N for _ in range(N)]
    for r, c in solution:
        grid[r][c] = 'S'

    return grid

