            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    num_regions = len(regions)

    # For each cell, track if it's a candidate
    # Use constraint propagation + backtracking

    # candidates[r][c] = True if cell can still have a star
    candidates = [[True] * N for _ in range(N)]

    def get_neighbors(r, c):
        """Get all adjacent cells including diagonals"""
        nbrs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    nbrs.append((nr, nc))
        return nbrs

    def solve_backtrack(stars, row, candidates):
        """Place stars row by row"""
        if row == N:
            # Check all regions have exactly 1 star
            region_counts = {}
            for (r, c) in stars:
                rid = data[r][c]
                region_counts[rid] = region_counts.get(rid, 0) + 1
            if len(region_counts) == num_regions and all(v == 1 for v in region_counts.values()):
                return stars[:]
            return None

        # Try placing a star in each column of this row
        for col in range(N):
            if not candidates[row][col]:
                continue

            rid = data[row][col]

            # Check column constraint: no other star in same column
            col_ok = True
            for (sr, sc) in stars:
