    valid_cols = []
    for r in range(N):
        cols = [c for c in range(N) if (r, c) not in obstacles]
        valid_cols.append(cols)

    # Track which columns are used and which cells are blocked by adjacency
    col_used = [False] * N
    # blocked_cols[c] = count of stars adjacent to column c (we use a different approach)
    # Instead, track blocked cells: set of (row, col) that are adjacent to placed stars

    # We'll use backtracking row by row with constraint propagation
    # For each row, try each valid column, check:
    # 1. Column not already used
    # 2. Cell not adjacent (including diagonal) to any already placed star
    # 3. Forward check: remaining rows must have enough valid options

    placed = []  # list of (row, col) for placed stars
    blocked = set()  # cells blocked by adjacency to placed stars

    def add_star(r, c):
        placed.append((r, c))
        col_used[c] = True
        # Add all adjacent cells (including diagonal) to blocked
        new_blocked = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
