        placed.pop()
        col_used[c] = False
        for cell in new_blocked:
            blocked.discard(cell)

    def forward_check(next_row):
        # Check that each remaining row (from next_row) has at least one valid column
        for r in range(next_row, N):
            has_option = False
            for c in valid_cols[r]:
                if not col_used[c] and (r, c) not in blocked:
                    has_option = True
                    break
            if not has_option:
                return False
        return True

