        if row == N:
            return len(placed) == N

        for c in valid_cols[row]:
            if col_used[c]:
                continue
            if (row, c) in blocked:
                continue

            new_blocked = add_star(row, c)

            if forward_check(row + 1):
                if backtrack(row + 1):
                    return True

            remove_star(row, c, new_blocked)

        return False

