                possible_stitches.append(((r, c), (r, c+1)))
            # Down neighbor
            if r + 1 < N and region[r][c] != region[r+1][c]:
                possible_stitches.append(((r, c), (r+1, c)))

    # Find all region boundary pairs - each pair of adjacent regions must have exactly one stitch
    boundary_pairs = set()
    for (r1, c1), (r2, c2) in possible_stitches:
        a, b = region[r1][c1], region[r2][c2]
        boundary_pairs.add((min(a, b), max(a, b)))

    # Group stitches by boundary pair
    boundary_to_stitches = {}
    for idx, ((r1, c1), (r2, c2)) in enumerate(possible_stitches):
        a, b = region[r1][c1], region[r2][c2]
        key = (min(a, b), max(a, b))
        if key not in boundary_to_stitches:
            boundary_to_stitches[key] = []
        boundary_to_stitches[key].append(idx)

    # For each hole, which stitches use it
    hole_to_stitches = {}
    for idx, ((r1, c1), (r2, c2)) in enumerate(possible_stitches):
        for h in [(r1, c1), (r2, c2)]:
            if h not in hole_to_stitches:
