    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))
                tree_set.add((r, c))

    num_trees = len(trees)

    # For each tree, find possible tent positions (orthogonally adjacent empty cells)
    tree_possible_tents = {}
    for idx, (tr, tc) in enumerate(trees):
        possible = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = tr+dr, tc+dc
            if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in tree_set:
                possible.append((nr, nc))
