    # We use constraint propagation + backtracking

    # Represent domains as sets
    domains = [set(tree_possible_tents[i]) for i in range(num_trees)]

    # Track tent placements: tent_pos -> tree_idx or None
    assignment = [None] * num_trees  # tree_idx -> tent_pos

