                if all(v == 1 for v in vals) or all(v == 2 for v in vals):
                    return False
        return True

    def check_2x2_partial(grid):
        """Check no 2x2 block is all same color, considering only filled cells"""
        for r in range(N-1):
            for c in range(N-1):
                vals = [grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]]
                if all(v == 1 for v in vals) or all(v == 2 for v in vals):
                    return False
